-- Canonical security catalog (no OIDs, data or credentials).
select jsonb_build_object(
 'roles',(select jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolbypassrls) order by rolname) from pg_roles where rolname like 'padelhub_%'),
 'memberships',(select jsonb_agg(jsonb_build_array(r.rolname,m.rolname,a.admin_option) order by r.rolname,m.rolname) from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member where r.rolname like 'padelhub_%' or m.rolname like 'padelhub_%'),
 'schemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),(select jsonb_agg(x::text order by x::text) from unnest(coalesce(nspacl,acldefault('n',nspowner))) x)) order by nspname) from pg_namespace where nspname in ('auth','public','private')),
 'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_userbyid(c.relowner),(select jsonb_agg(x::text order by x::text) from unnest(coalesce(c.relacl,acldefault(case when c.relkind='S' then 's'::"char" else 'r'::"char" end,c.relowner))) x),c.relrowsecurity,c.relforcerowsecurity) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','public','private') and c.relkind in ('r','v','S','m','p')),
 'columns',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attname,(select jsonb_agg(x::text order by x::text) from unnest(a.attacl) x)) order by n.nspname,c.relname,a.attname) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','public','private') and a.attacl is not null),
 'functions',(select jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_userbyid(p.proowner),(select jsonb_agg(x::text order by x::text) from unnest(coalesce(p.proacl,acldefault('f',p.proowner))) x),p.prosecdef,p.proconfig) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('auth','public','private')),
 'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('auth','public','private')),
 'defaults',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype,(select jsonb_agg(x::text order by x::text) from unnest(d.defaclacl) x)) order by d.defaclrole::regrole::text,n.nspname,d.defaclobjtype) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('auth','public','private'))
)::text;
